#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string N;
    if (!(cin >> N)) return 0;

    int M;
    if (!(cin >> M)) return 0;

    // Tabela de mapeamento de letras 'a'..'z' para dígitos '2'..'9'
    const char letter_to_digit[26] = {
        '2', '2', '2',      // a, b, c
        '3', '3', '3',      // d, e, f
        '4', '4', '4',      // g, h, i
        '5', '5', '5',      // j, k, l
        '6', '6', '6',      // m, n, o
        '7', '7', '7', '7', // p, q, r, s
        '8', '8', '8',      // t, u, v
        '9', '9', '9', '9'  // w, x, y, z
    };

    int count = 0;
    for (int i = 0; i < M; ++i) {
        string word;
        cin >> word;

        if (word.length() != N.length()) {
            continue;
        }

        bool match = true;
        for (size_t j = 0; j < word.length(); ++j) {
            if (letter_to_digit[word[j] - 'a'] != N[j]) {
                match = false;
                break;
            }
        }

        if (match) {
            count++;
        }
    }

    cout << count << "\n";

    return 0;
}
